insert into public.finish_levels (id, key, name_es, name_en, description_es, description_en, includes_es, includes_en, price_multiplier, custom_price_per_m2_usd_cents, sort_order) values
  ('d4000000-0000-4000-8000-000000000001', 'basic', 'Básico', 'Basic', 'Una casa sólida y bien terminada, con materiales económicos y durables.', 'A solid, well-finished home with affordable, durable materials.', array['Piso de cerámica', 'Paredes repelladas y pintadas', 'Puertas de madera de pino', 'Cocina con gabinetes básicos', 'Sanitarios y grifería estándar']::text[], array['Ceramic tile floors', 'Plastered and painted walls', 'Pine wood doors', 'Kitchen with basic cabinets', 'Standard toilets and faucets']::text[], 0.86, 44000, 1),
  ('d4000000-0000-4000-8000-000000000002', 'standard', 'Estándar', 'Standard', 'Lo que elige la mayoría: buenos materiales y detalles que se notan.', 'What most people choose: good materials and details you notice.', array['Piso de porcelanato', 'Cielo falso de tablayeso', 'Cocina con gabinetes y desayunador', 'Ventanas de aluminio y vidrio', 'Puertas de madera sólida']::text[], array['Porcelain tile floors', 'Drywall drop ceilings', 'Kitchen with cabinets and breakfast bar', 'Aluminum and glass windows', 'Solid wood doors']::text[], 1, 52000, 2),
  ('d4000000-0000-4000-8000-000000000003', 'premium', 'Premium', 'Premium', 'Acabados de primera para una casa que luce y dura.', 'Top-quality finishes for a home that looks great and lasts.', array['Porcelanato de formato grande', 'Cocina con isla y cubierta de granito', 'Duchas con puerta de vidrio templado', 'Iluminación LED empotrada', 'Ventanas con vidrio doble']::text[], array['Large-format porcelain tile', 'Kitchen island with granite countertop', 'Showers with tempered glass doors', 'Recessed LED lighting', 'Double-glazed windows']::text[], 1.32, 69000, 3)
