  ('e5000000-0000-4000-8000-000000000005', 'water_heater', 'Calentador de agua solar', 'Solar water heater', 'Agua caliente en la ducha sin gastar electricidad.', 'Hot showers without using electricity.', 'fixed', 85000, 1, 1, 1, false, 'installations', 5),
  ('e5000000-0000-4000-8000-000000000006', 'air_conditioning', 'Aire acondicionado', 'Air conditioning', 'Minisplit de 12,000 BTU instalado. Se cobra por unidad.', '12,000 BTU mini-split, installed. Priced per unit.', 'per_unit', 78000, 1, 6, 2, false, 'installations', 6),
  ('e5000000-0000-4000-8000-000000000007', 'covered_carport', 'Cochera techada', 'Covered carport', 'Espacio techado para un vehículo, con piso de concreto.', 'Covered space for one vehicle with a concrete floor.', 'fixed', 280000, 1, 1, 1, true, 'roof', 7),
  ('e5000000-0000-4000-8000-000000000008', 'electric_gate', 'Portón eléctrico', 'Electric gate', 'Portón corredizo de metal con motor y dos controles.', 'Sliding metal gate with motor and two remotes.', 'fixed', 145000, 1, 1, 1, true, 'finishes', 8)
