  ('c7000000-0000-4000-8000-000000000006', 'foundation', 'structure', 'steel_framing', 'Steel framing', 'Steel framing', 'Losa de cimentación y estructura de perfiles de acero galvanizado. Más rápida de levantar.', 'Slab foundation and a galvanized light-steel frame. Faster to build.', 'footprint_m2', 8500, 6500, 2.2, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000007', 'foundation', 'footing_waterproofing', 'asphalt_emulsion', 'Emulsión asfáltica', 'Asphalt emulsion', 'Capa de asfalto que protege zapatas y solera de la humedad del suelo.', 'An asphalt coat that protects footings and beams from ground moisture.', 'footprint_m2', 300, 6000, 0.3, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000008', 'foundation', 'footing_waterproofing', 'cementitious', 'Impermeabilizante cementicio', 'Cementitious waterproofing', 'Mortero impermeable que se aplica con brocha. Más resistente que el asfalto.', 'A brush-applied waterproof mortar. Tougher than asphalt.', 'footprint_m2', 450, 6000, 0.3, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000009', 'foundation', 'footing_waterproofing', 'membrane', 'Membrana impermeable', 'Waterproof membrane', 'Lámina que envuelve la cimentación. La mejor protección en terrenos húmedos.', 'A sheet that wraps the foundation. The best protection on damp ground.', 'footprint_m2', 700, 7000, 0.4, false, true, true, 3),
  ('c7000000-0000-4000-8000-000000000010', 'foundation', 'ground_slab', 'concrete_ground_slab', 'Firme de concreto', 'Concrete ground slab', 'Piso de concreto de la planta baja, sobre relleno compactado.', 'The ground-floor concrete slab, on compacted fill.', 'footprint_m2', 1200, 6000, 1, false, true, true, 1),
  ('c7000000-0000-4000-8000-000000000011', 'grey_work', 'walls', 'concrete_block', 'Sistema bloque', 'Block system', 'Bloque de concreto, pegablock y repello. El sistema más usado en Honduras.', 'Concrete block, block adhesive mortar and plaster. The most common system in Honduras.', 'construction_m2', 11500, 5500, 6, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000012', 'grey_work', 'walls', 'polystyrene_panel', 'Sistema poliestireno', 'Polystyrene system', 'Panel de poliestireno, malla y basecoat. Aísla del calor y se instala más rápido.', 'Polystyrene panel, mesh and basecoat. Keeps heat out and goes up faster.', 'construction_m2', 10500, 6500, 4.5, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000013', 'grey_work', 'upper_slab', 'solid_slab', 'Losa sólida', 'Solid slab', 'Losa de concreto armado entre la planta baja y la alta.', 'A reinforced concrete slab between the ground and upper floor.', 'upper_floor_m2', 8500, 5500, 2.5, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000014', 'grey_work', 'upper_slab', 'joist_and_block_slab', 'Losa aligerada', 'Joist-and-block slab', 'Vigueta y bovedilla con capa de concreto. Más liviana y económica.', 'Precast joists and filler blocks with a concrete topping. Lighter and cheaper.', 'upper_floor_m2', 7000, 6000, 2, false, true, true, 2),
