  ('c7000000-0000-4000-8000-000000000019', 'roof', 'roof_cover', 'aluzinc_sheet', 'Lámina de aluzinc', 'Aluzinc sheet', 'Lámina metálica con protección contra el óxido. Liviana y duradera.', 'Rust-protected metal sheet. Light and durable.', 'footprint_m2', 1800, 7000, 0.6, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000020', 'roof', 'roof_cover', 'clay_tile_over_sheet', 'Teja sobre lámina', 'Clay tile over sheet', 'Teja de barro sobre lámina. Fresca y tradicional.', 'Clay tile over a metal sheet. Cool and traditional.', 'footprint_m2', 3400, 7000, 1.2, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000021', 'roof', 'roof_cover', 'concrete_roof_slab', 'Losa de concreto', 'Concrete roof slab', 'Techo plano de concreto. Permite construir otro piso después.', 'A flat concrete roof. Lets you add another floor later.', 'footprint_m2', 7000, 5500, 2.5, false, true, true, 3),
  ('c7000000-0000-4000-8000-000000000022', 'roof', 'roof_insulation', 'reflective_foil', 'Foil reflectivo', 'Reflective foil', 'Lámina que refleja el calor del sol bajo el techo.', 'A sheet under the roof that reflects the sun''s heat.', 'footprint_m2', 400, 7500, 0.2, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000023', 'roof', 'roof_insulation', 'polystyrene_insulation', 'Poliestireno', 'Polystyrene boards', 'Planchas aislantes: la casa se mantiene más fresca.', 'Insulating boards: the house stays cooler.', 'footprint_m2', 700, 7500, 0.3, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000024', 'roof', 'roof_insulation', 'no_insulation', 'Sin aislamiento', 'No insulation', 'Solo la cubierta.', 'Roof cover only.', 'fixed', 0, 0, 0, false, true, true, 3),
  ('c7000000-0000-4000-8000-000000000025', 'roof', 'ceiling', 'gypsum_board', 'Tablayeso', 'Gypsum board', 'Cielo falso de tablayeso con acabado liso.', 'A smooth gypsum board ceiling.', 'footprint_m2', 1600, 6000, 1, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000026', 'roof', 'ceiling', 'pvc_ceiling', 'PVC', 'PVC', 'Cielo de PVC. Resiste la humedad y es fácil de limpiar.', 'PVC ceiling. Handles humidity and is easy to clean.', 'footprint_m2', 1300, 6500, 0.8, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000027', 'roof', 'ceiling', 'no_ceiling', 'Sin cielo falso', 'No ceiling', 'La estructura del techo queda a la vista.', 'The roof structure stays exposed.', 'fixed', 0, 0, 0, false, true, true, 3),
