  ('c7000000-0000-4000-8000-000000000029', 'finishes', 'floors', 'porcelain_tile', 'Porcelanato', 'Porcelain tile', 'Piso de porcelanato de 60 × 60 cm. Más duro y elegante.', '60 × 60 cm porcelain tile. Harder and more elegant.', 'construction_m2', 3800, 6500, 1.6, false, true, true, 2),
