  ('c7000000-0000-4000-8000-000000000031', 'finishes', 'doors', 'solid_wood_doors', 'Madera', 'Solid wood', 'Puertas de madera sólida con marco y chapa.', 'Solid wood doors with frame and lock.', 'construction_m2', 1400, 7500, 0.4, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000032', 'finishes', 'doors', 'mdf_doors', 'MDF', 'MDF', 'Puertas de MDF pintadas. Las más económicas.', 'Painted MDF doors. The most affordable.', 'construction_m2', 900, 7500, 0.4, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000033', 'finishes', 'doors', 'metal_doors', 'Metal', 'Metal', 'Puertas metálicas. Más seguridad en las entradas.', 'Metal doors. Extra security at the entrances.', 'construction_m2', 1100, 7500, 0.4, false, true, true, 3),
  ('c7000000-0000-4000-8000-000000000034', 'finishes', 'windows', 'aluminum_windows', 'Aluminio y vidrio', 'Aluminum and glass', 'Ventanas corredizas de aluminio con vidrio claro.', 'Sliding aluminum windows with clear glass.', 'construction_m2', 1600, 7500, 0.4, true, true, true, 1),
  ('c7000000-0000-4000-8000-000000000035', 'finishes', 'windows', 'pvc_windows', 'PVC', 'PVC', 'Ventanas de PVC. Aíslan mejor del ruido y del calor.', 'PVC windows. Better insulation from noise and heat.', 'construction_m2', 2200, 7500, 0.5, false, true, true, 2),
  ('c7000000-0000-4000-8000-000000000036', 'finishes', 'bathrooms', 'basic_fixtures', 'Línea básica', 'Basic line', 'Inodoro, lavamanos y ducha de línea económica, con su enchape.', 'Entry-level toilet, sink and shower, with wall tile.', 'per_bathroom', 65000, 8000, 0.4, false, true, true, 1),
  ('c7000000-0000-4000-8000-000000000037', 'finishes', 'bathrooms', 'mid_fixtures', 'Línea media', 'Mid-range line', 'Artefactos de marca reconocida, enchape completo y espejo.', 'Well-known brand fixtures, full wall tile and mirror.', 'per_bathroom', 110000, 8000, 0.5, true, true, true, 2),
