insert into public.house_models (id, slug, name_es, name_en, summary_es, summary_en, description_es, description_en, area_m2, bedrooms, bathrooms, floors, min_lot_area_m2, min_lot_front_m, build_weeks, base_price_usd_cents, floor_plan, is_active, is_example, sort_order) values
  ('c3000000-0000-4000-8000-000000000001', 'modelo-lempira', 'Modelo Lempira', 'Lempira model', 'Casa compacta de 2 cuartos, ideal para empezar en un terreno pequeño.', 'Compact 2-bedroom home, ideal to start on a small lot.', 'Sala y comedor juntos, cocina con área de pila, dos cuartos y un baño completo. Se construye en un terreno desde 120 m² y se puede ampliar después hacia el fondo.', 'Combined living and dining room, kitchen with a laundry area, two bedrooms and a full bathroom. It fits on lots from 120 m² and can be extended toward the back later.', 58, 2, 1, 1, 120, 8, 18, 2950000, '[{"room":"porch","areaM2":3,"floor":1},{"room":"living_dining","areaM2":18,"floor":1},{"room":"kitchen","areaM2":7,"floor":1},{"room":"laundry","areaM2":3,"floor":1},{"room":"hallway","areaM2":3,"floor":1},{"room":"bathroom","areaM2":4,"floor":1},{"room":"primary_bedroom","areaM2":11,"floor":1},{"room":"bedroom","areaM2":9,"floor":1}]'::jsonb, true, true, 1),
  ('c3000000-0000-4000-8000-000000000002', 'modelo-copan', 'Modelo Copán', 'Copán model', '3 cuartos y 2 baños en una sola planta. El más pedido por familias.', '3 bedrooms and 2 bathrooms on one floor. The family favorite.', 'Una planta con sala y comedor amplios, cocina, área de lavandería, tres cuartos y dos baños. El cuarto principal tiene su propio baño.', 'A single floor with a spacious living and dining area, kitchen, laundry area, three bedrooms and two bathrooms. The primary bedroom has its own bathroom.', 86, 3, 2, 1, 160, 10, 22, 4380000, '[{"room":"living_dining","areaM2":24,"floor":1},{"room":"kitchen","areaM2":9,"floor":1},{"room":"laundry","areaM2":4,"floor":1},{"room":"hallway","areaM2":6,"floor":1},{"room":"primary_bedroom","areaM2":14,"floor":1},{"room":"bathroom","areaM2":4.5,"floor":1},{"room":"bedroom","areaM2":10,"floor":1},{"room":"bedroom","areaM2":10,"floor":1},{"room":"bathroom","areaM2":4.5,"floor":1}]'::jsonb, true, true, 2),
  ('c3000000-0000-4000-8000-000000000003', 'modelo-ceiba', 'Modelo Ceiba', 'Ceiba model', '3 cuartos, 2 baños y cochera, con sala y comedor separados.', '3 bedrooms, 2 bathrooms and a carport, with separate living and dining rooms.', 'Una planta con cochera para un carro, sala y comedor separados, cocina amplia, lavandería, tres cuartos y dos baños. Pensado para terrenos desde 200 m².', 'A single floor with a one-car carport, separate living and dining rooms, a large kitchen, laundry, three bedrooms and two bathrooms. Designed for lots from 200 m².', 104, 3, 2, 1, 200, 12, 24, 5290000, '[{"room":"carport","areaM2":14,"floor":1},{"room":"living","areaM2":16,"floor":1},{"room":"dining","areaM2":10,"floor":1},{"room":"kitchen","areaM2":10,"floor":1},{"room":"laundry","areaM2":4,"floor":1},{"room":"hallway","areaM2":6,"floor":1},{"room":"primary_bedroom","areaM2":15,"floor":1},{"room":"bathroom","areaM2":5,"floor":1},{"room":"bedroom","areaM2":10,"floor":1},{"room":"bedroom","areaM2":10,"floor":1},{"room":"bathroom","areaM2":4,"floor":1}]'::jsonb, true, true, 3),
  ('c3000000-0000-4000-8000-000000000004', 'modelo-pico-bonito', 'Modelo Pico Bonito', 'Pico Bonito model', 'Dos plantas en un terreno angosto: 3 cuartos y 2 baños y medio.', 'Two floors on a narrow lot: 3 bedrooms and 2.5 bathrooms.', 'Abajo, sala, comedor, cocina, medio baño y lavandería. Arriba, tres cuartos y dos baños. Aprovecha bien terrenos de 9 metros de frente.', 'Downstairs: living room, dining room, kitchen, half bath and laundry. Upstairs: three bedrooms and two bathrooms. It makes the most of lots 9 meters wide.', 122, 3, 2.5, 2, 160, 9, 28, 6450000, '[{"room":"porch","areaM2":6,"floor":1},{"room":"living","areaM2":18,"floor":1},{"room":"dining","areaM2":10,"floor":1},{"room":"kitchen","areaM2":11,"floor":1},{"room":"half_bath","areaM2":3,"floor":1},{"room":"laundry","areaM2":4,"floor":1},{"room":"stairs","areaM2":5,"floor":1},{"room":"primary_bedroom","areaM2":17,"floor":2},{"room":"bathroom","areaM2":6,"floor":2},{"room":"bedroom","areaM2":11,"floor":2},{"room":"bedroom","areaM2":11,"floor":2},{"room":"bathroom","areaM2":5,"floor":2},{"room":"hallway","areaM2":10,"floor":2},{"room":"stairs","areaM2":5,"floor":2}]'::jsonb, true, true, 4),
  ('c3000000-0000-4000-8000-000000000005', 'modelo-morazan', 'Modelo Morazán', 'Morazán model', 'Casa de dos plantas con 4 cuartos y 3 baños, con cuarto de visitas abajo.', 'Two-story home with 4 bedrooms and 3 bathrooms, including a downstairs guest room.', 'Abajo, sala, comedor, cocina, terraza, lavandería y un cuarto con baño para visitas o para un familiar mayor. Arriba, tres cuartos y dos baños.', 'Downstairs: living room, dining room, kitchen, terrace, laundry and a bedroom with bathroom for guests or an older relative. Upstairs: three bedrooms and two bathrooms.', 148, 4, 3, 2, 220, 11, 32, 7840000, '[{"room":"living","areaM2":20,"floor":1},{"room":"dining","areaM2":12,"floor":1},{"room":"kitchen","areaM2":13,"floor":1},{"room":"terrace","areaM2":8,"floor":1},{"room":"bedroom","areaM2":11,"floor":1},{"room":"bathroom","areaM2":4.5,"floor":1},{"room":"laundry","areaM2":5,"floor":1},{"room":"stairs","areaM2":5,"floor":1},{"room":"primary_bedroom","areaM2":18,"floor":2},{"room":"bathroom","areaM2":6,"floor":2},{"room":"bedroom","areaM2":12,"floor":2},{"room":"bedroom","areaM2":12,"floor":2},{"room":"bathroom","areaM2":5,"floor":2},{"room":"hallway","areaM2":11.5,"floor":2},{"room":"stairs","areaM2":5,"floor":2}]'::jsonb, true, true, 5)
insert into public.homes (id, slug, code, title_es, title_en, summary_es, summary_en, description_es, description_en, department_id, municipality_id, neighborhood, latitude, longitude, construction_status, listing_status, price_usd_cents, bedrooms, bathrooms, construction_area_m2, lot_area_m2, floors, parking_spaces, features, house_model_id, video_url, tour_url, estimated_delivery, is_example, sort_order) values
  ('a1000000-0000-4000-8000-000000000001', 'casa-copan-choloma', 'CF-C-101', 'Casa de 3 cuartos en Choloma', '3-bedroom home in Choloma', 'Lista para entrar, en residencial con acceso controlado. Modelo Copán.', 'Move-in ready, in a gated neighborhood. Copán model.', 'Casa de una planta con sala y comedor amplios, cocina con gabinetes, área de pila y patio trasero. El residencial tiene portón con vigilancia y calles pavimentadas. A 15 minutos de San Pedro Sula.', 'Single-story home with a spacious living and dining area, kitchen with cabinets, laundry area and backyard. The neighborhood has a guarded gate and paved streets. 15 minutes from San Pedro Sula.', 5, (select id from public.municipalities where department_id = 5 and name = 'Choloma'), 'Residencial con acceso controlado, sector norte', 15.622, -87.948, 'ready', 'published', 4650000, 3, 2, 86, 160, 1, 1, array['integrated_kitchen', 'ceramic_floors', 'laundry_area', 'patio', 'gated_community', 'elevated_tank']::text[], 'c3000000-0000-4000-8000-000000000002', null, null, null, true, 1),
  ('a1000000-0000-4000-8000-000000000002', 'casa-lempira-villanueva', 'CF-C-102', 'Casa de 2 cuartos en Villanueva', '2-bedroom home in Villanueva', 'Casa compacta y terminada, con patio para ampliar más adelante.', 'Compact, finished home with a yard to expand later.', 'Dos cuartos, un baño, sala y comedor juntos y cocina con pila. El terreno deja espacio para agregar un cuarto más. Cerca de escuelas y del centro de Villanueva.', 'Two bedrooms, one bathroom, combined living and dining room and a kitchen with laundry sink. The lot leaves room to add another bedroom. Close to schools and downtown Villanueva.', 5, (select id from public.municipalities where department_id = 5 and name = 'Villanueva'), 'Colonia residencial, sector este', 15.322, -88.004, 'ready', 'published', 3390000, 2, 1, 58, 130, 1, 1, array['laundry_area', 'patio', 'ceramic_floors']::text[], 'c3000000-0000-4000-8000-000000000001', null, null, null, true, 2),
  ('a1000000-0000-4000-8000-000000000003', 'casa-ceiba-san-pedro-sula', 'CF-C-103', 'Casa con cochera en San Pedro Sula', 'Home with carport in San Pedro Sula', 'En construcción, con muro perimetral y portón eléctrico. Modelo Ceiba.', 'Under construction, with perimeter wall and electric gate. Ceiba model.', 'Tres cuartos, dos baños, sala y comedor separados y cochera techada. Va por la etapa de techo: puedes ver el avance con fotos antes de decidir. Entrega estimada en abril de 2027.', 'Three bedrooms, two bathrooms, separate living and dining rooms and a covered carport. It is at the roof stage: you can see the progress in photos before deciding. Estimated handover in April 2027.', 5, (select id from public.municipalities where department_id = 5 and name = 'San Pedro Sula'), 'Residencial privado, sector sur', 15.531, -88.047, 'under_construction', 'published', 6800000, 3, 2, 104, 210, 1, 1, array['carport', 'integrated_kitchen', 'ceramic_floors', 'laundry_area', 'perimeter_wall', 'electric_gate', 'gated_community']::text[], 'c3000000-0000-4000-8000-000000000003', null, null, '2027-04-30', true, 3),
  ('a1000000-0000-4000-8000-000000000004', 'casa-dos-plantas-san-pedro-sula', 'CF-C-104', 'Casa de dos plantas en San Pedro Sula', 'Two-story home in San Pedro Sula', '4 cuartos, 3 baños, terraza y aire acondicionado. Apartada.', '4 bedrooms, 3 bathrooms, terrace and air conditioning. Reserved.', 'Casa amplia de dos plantas con garaje para dos carros, cocina integrada, terraza arriba, walk-in closet en el cuarto principal y cisterna. Está apartada; si te interesa una parecida, escríbenos.', 'Spacious two-story home with a two-car garage, integrated kitchen, upstairs terrace, walk-in closet in the primary bedroom and a cistern. It is reserved; if you want a similar one, message us.', 5, (select id from public.municipalities where department_id = 5 and name = 'San Pedro Sula'), 'Residencial privado, sector oeste', 15.482, -88.01, 'ready', 'reserved', 11800000, 4, 3, 160, 250, 2, 2, array['covered_garage', 'integrated_kitchen', 'ceramic_floors', 'walk_in_closet', 'terrace', 'water_cistern', 'air_conditioning', 'gated_community', 'electric_gate', 'laundry_area']::text[], null, null, null, null, true, 4),
  ('a1000000-0000-4000-8000-000000000005', 'casa-puerto-cortes', 'CF-C-105', 'Casa con jardín en Puerto Cortés', 'Home with garden in Puerto Cortés', '3 cuartos y jardín, a minutos de la playa.', '3 bedrooms and a garden, minutes from the beach.', 'Casa de una planta con tres cuartos, dos baños, jardín al frente y patio atrás. Tiene calentador de agua y piso de cerámica en toda la casa.', 'Single-story home with three bedrooms, two bathrooms, a front garden and backyard. It has a water heater and ceramic floors throughout.', 5, (select id from public.municipalities where department_id = 5 and name = 'Puerto Cortés'), 'Colonia cercana al bulevar', 15.816, -87.94, 'ready', 'published', 5750000, 3, 2, 96, 180, 1, 1, array['patio', 'garden', 'laundry_area', 'water_heater', 'ceramic_floors']::text[], null, null, null, null, true, 5),
  ('a1000000-0000-4000-8000-000000000006', 'casa-morazan-tegucigalpa', 'CF-C-106', 'Casa en preventa en Tegucigalpa', 'Presale home in Tegucigalpa', '4 cuartos y estudio, en preventa. Pagas por etapas mientras se construye.', '4 bedrooms and a study, in presale. You pay in stages while it is built.', 'Modelo Morazán de dos plantas, con cuarto y baño abajo para visitas, terraza, estudio y cisterna. Al comprar en preventa pagas por etapas y ves cada avance con fotos. Entrega estimada en septiembre de 2027.', 'Two-story Morazán model with a downstairs bedroom and bath for guests, a terrace, a study and a cistern. Buying in presale you pay in stages and see every update with photos. Estimated handover in September 2027.', 8, (select id from public.municipalities where department_id = 8 and name = 'Distrito Central'), 'Residencial nuevo, salida al sur', 14.058, -87.18, 'presale', 'published', 9600000, 4, 3, 148, 230, 2, 2, array['integrated_kitchen', 'ceramic_floors', 'terrace', 'walk_in_closet', 'water_cistern', 'elevated_tank', 'gated_community', 'laundry_area', 'study']::text[], 'c3000000-0000-4000-8000-000000000005', null, null, '2027-09-30', true, 6),
  ('a1000000-0000-4000-8000-000000000007', 'casa-campo-santa-lucia', 'CF-C-107', 'Casa de campo en Santa Lucía', 'Country home in Santa Lucía', 'Clima fresco, terreno de 600 m² y paneles solares.', 'Cool climate, 600 m² lot and solar panels.', 'Casa de una planta en las afueras de Tegucigalpa, con jardín grande, terraza, cochera techada, cisterna, calentador de agua y paneles solares. Ideal para retirarse o para la familia.', 'Single-story home on the outskirts of Tegucigalpa with a large garden, terrace, covered garage, cistern, water heater and solar panels. Ideal for retirement or for the family.', 8, (select id from public.municipalities where department_id = 8 and name = 'Santa Lucía'), 'Zona residencial de montaña', 14.112, -87.12, 'ready', 'published', 13900000, 3, 2.5, 140, 600, 1, 2, array['garden', 'terrace', 'patio', 'water_cistern', 'water_heater', 'solar_panels', 'perimeter_wall', 'covered_garage', 'integrated_kitchen']::text[], null, null, null, null, true, 7),
  ('a1000000-0000-4000-8000-000000000008', 'casa-pico-bonito-la-ceiba', 'CF-C-108', 'Casa de dos plantas en La Ceiba', 'Two-story home in La Ceiba', 'En construcción, con aire acondicionado. Modelo Pico Bonito.', 'Under construction, with air conditioning. Pico Bonito model.', 'Tres cuartos arriba y sala, comedor y cocina abajo, con medio baño para visitas. Va por la etapa de paredes. Entrega estimada en marzo de 2027.', 'Three bedrooms upstairs; living room, dining room and kitchen downstairs, with a half bath for guests. It is at the walls stage. Estimated handover in March 2027.', 1, (select id from public.municipalities where department_id = 1 and name = 'La Ceiba'), 'Residencial con acceso controlado', 15.768, -86.79, 'under_construction', 'published', 7250000, 3, 2.5, 122, 170, 2, 1, array['integrated_kitchen', 'ceramic_floors', 'air_conditioning', 'laundry_area', 'elevated_tank', 'gated_community']::text[], 'c3000000-0000-4000-8000-000000000004', null, null, '2027-03-31', true, 8),
  ('a1000000-0000-4000-8000-000000000009', 'casa-tela', 'CF-C-109', 'Casa de 2 cuartos en Tela', '2-bedroom home in Tela', 'Cerca de la playa, con patio y jardín.', 'Close to the beach, with a yard and garden.', 'Dos cuartos, cada uno con su baño, sala, comedor y cocina. Tiene aire acondicionado, calentador de agua y un patio grande con árboles.', 'Two bedrooms, each with its own bathroom, plus living room, dining room and kitchen. It has air conditioning, a water heater and a large yard with trees.', 1, (select id from public.municipalities where department_id = 1 and name = 'Tela'), 'Barrio tranquilo, cerca de la costa', 15.776, -87.455, 'ready', 'published', 5400000, 2, 2, 80, 220, 1, 1, array['patio', 'garden', 'water_heater', 'air_conditioning', 'ceramic_floors']::text[], null, null, null, null, true, 9),
  ('a1000000-0000-4000-8000-000000000010', 'casa-siguatepeque', 'CF-C-110', 'Casa con jardín en Siguatepeque', 'Home with garden in Siguatepeque', '3 cuartos en clima fresco, con cisterna.', '3 bedrooms in a cool climate, with a cistern.', 'Casa de una planta con tres cuartos, dos baños, jardín y patio. Cuenta con cisterna. Siguatepeque está a medio camino entre Tegucigalpa y San Pedro Sula.', 'Single-story home with three bedrooms, two bathrooms, a garden and a yard. It has a cistern. Siguatepeque is halfway between Tegucigalpa and San Pedro Sula.', 3, (select id from public.municipalities where department_id = 3 and name = 'Siguatepeque'), 'Colonia residencial, sector norte', 14.606, -87.83, 'ready', 'published', 4980000, 3, 2, 92, 200, 1, 1, array['garden', 'patio', 'laundry_area', 'ceramic_floors', 'water_cistern']::text[], null, null, null, null, true, 10),
  ('a1000000-0000-4000-8000-000000000011', 'casa-lempira-comayagua', 'CF-C-111', 'Casa en preventa en Comayagua', 'Presale home in Comayagua', 'La opción más accesible: 2 cuartos en preventa. Modelo Lempira.', 'The most affordable option: 2 bedrooms in presale. Lempira model.', 'Casa de dos cuartos y un baño en residencial nuevo. En preventa pagas por etapas y ves cada avance. Entrega estimada en junio de 2027.', 'Two-bedroom, one-bathroom home in a new neighborhood. In presale you pay in stages and see every update. Estimated handover in June 2027.', 3, (select id from public.municipalities where department_id = 3 and name = 'Comayagua'), 'Residencial nuevo, salida a Tegucigalpa', 14.452, -87.64, 'presale', 'published', 3150000, 2, 1, 58, 120, 1, 1, array['laundry_area', 'ceramic_floors', 'gated_community']::text[], 'c3000000-0000-4000-8000-000000000001', null, null, '2027-06-30', true, 11),
  ('a1000000-0000-4000-8000-000000000012', 'casa-la-lima', 'CF-C-112', 'Casa de 3 cuartos en La Lima', '3-bedroom home in La Lima', 'Lista para entrar, cerca del aeropuerto de San Pedro Sula.', 'Move-in ready, close to the San Pedro Sula airport.', 'Tres cuartos, baño completo y medio baño, sala, comedor, cocina y área de pila. Tiene tanque elevado. A 10 minutos del aeropuerto.', 'Three bedrooms, a full bath and a half bath, living room, dining room, kitchen and laundry area. It has an elevated water tank. 10 minutes from the airport.', 5, (select id from public.municipalities where department_id = 5 and name = 'La Lima'), 'Colonia residencial, sector central', 15.428, -87.91, 'ready', 'published', 4100000, 3, 1.5, 78, 140, 1, 1, array['laundry_area', 'patio', 'ceramic_floors', 'elevated_tank']::text[], null, null, null, null, true, 12)
insert into public.lots (id, slug, code, title_es, title_en, summary_es, summary_en, description_es, description_en, department_id, municipality_id, neighborhood, latitude, longitude, listing_status, price_usd_cents, area_m2, front_m, depth_m, has_water, has_electricity, has_sewer, road_access, legal_status, topography, is_example, sort_order) values
  ('b2000000-0000-4000-8000-000000000001', 'terreno-choloma', 'CF-T-201', 'Terreno de 200 m² en Choloma', '200 m² lot in Choloma', 'Plano, con todos los servicios y escritura en regla.', 'Flat, with all utilities and a clear title.', 'Terreno plano de 10 por 20 metros en colonia con calle pavimentada. Tiene agua, luz y alcantarillado. Cabe el Modelo Copán.', 'Flat 10 by 20 meter lot in a neighborhood with a paved street. It has water, electricity and sewer. The Copán model fits.', 5, (select id from public.municipalities where department_id = 5 and name = 'Choloma'), 'Colonia con calle pavimentada', 15.61, -87.96, 'published', 1280000, 200, 10, 20, true, true, true, 'paved', 'full_title', 'flat', true, 1),
  ('b2000000-0000-4000-8000-000000000002', 'terreno-villanueva', 'CF-T-202', 'Terreno de 300 varas en Villanueva', '300-vara lot in Villanueva', 'Agua y luz, calle de balastre. Escritura en regla.', 'Water and electricity, gravel road. Clear title.', 'Terreno de 210 m² (unas 300 varas cuadradas), plano y con agua y luz. La calle es de balastre. Buen precio para construir el Modelo Copán o el Lempira.', '210 m² lot (about 300 square varas), flat and with water and electricity. The road is gravel. A good price to build the Copán or Lempira model.', 5, (select id from public.municipalities where department_id = 5 and name = 'Villanueva'), 'Lotificación nueva, sector oeste', 15.31, -88.01, 'published', 1450000, 210, 10.5, 20, true, true, false, 'gravel', 'full_title', 'flat', true, 2),
  ('b2000000-0000-4000-8000-000000000003', 'terreno-san-pedro-sula', 'CF-T-203', 'Terreno en residencial de San Pedro Sula', 'Lot in a San Pedro Sula neighborhood', '250 m² en residencial privado, con todos los servicios.', '250 m² in a gated neighborhood, with all utilities.', 'Terreno plano dentro de residencial con portón y vigilancia. Calles pavimentadas, agua, luz y alcantarillado. Cabe el Modelo Ceiba con cochera.', 'Flat lot inside a gated, guarded neighborhood. Paved streets, water, electricity and sewer. The Ceiba model with carport fits.', 5, (select id from public.municipalities where department_id = 5 and name = 'San Pedro Sula'), 'Residencial privado, sector sur', 15.525, -88.055, 'published', 3200000, 250, 12.5, 20, true, true, true, 'paved', 'full_title', 'flat', true, 3),
  ('b2000000-0000-4000-8000-000000000004', 'terreno-omoa', 'CF-T-204', 'Terreno con vista en Omoa', 'Lot with a view in Omoa', '600 m² con un poco de pendiente y vista a las montañas.', '600 m² with a gentle slope and mountain views.', 'Terreno grande con luz y acceso por calle de tierra. El agua se puede conectar a la red de la aldea. Tiene título de dominio útil.', 'Large lot with electricity and dirt road access. Water can be connected to the village network. It has a useful-domain (municipal) title.', 5, (select id from public.municipalities where department_id = 5 and name = 'Omoa'), 'Aldea en la carretera a Guatemala', 15.75, -88.05, 'published', 2200000, 600, 20, 30, false, true, false, 'dirt', 'useful_domain', 'gentle_slope', true, 4),
  ('b2000000-0000-4000-8000-000000000005', 'terreno-santa-lucia', 'CF-T-205', 'Terreno de 700 m² en Santa Lucía', '700 m² lot in Santa Lucía', 'Clima fresco, calle pavimentada y escritura en regla.', 'Cool climate, paved road and clear title.', 'Terreno con leve pendiente y árboles de pino, a 20 minutos de Tegucigalpa. Tiene agua y luz; el desagüe se resuelve con fosa séptica.', 'Lot with a gentle slope and pine trees, 20 minutes from Tegucigalpa. It has water and electricity; drainage uses a septic tank.', 8, (select id from public.municipalities where department_id = 8 and name = 'Santa Lucía'), 'Zona residencial de montaña', 14.118, -87.115, 'published', 4500000, 700, 25, 28, true, true, false, 'paved', 'full_title', 'gentle_slope', true, 5),
  ('b2000000-0000-4000-8000-000000000006', 'terreno-tegucigalpa', 'CF-T-206', 'Terreno en Tegucigalpa', 'Lot in Tegucigalpa', '240 m² en residencial con servicios. Apartado.', '240 m² in a neighborhood with utilities. Reserved.', 'Terreno plano en residencial con calles pavimentadas y todos los servicios. Está apartado; tenemos otros parecidos en la zona.', 'Flat lot in a neighborhood with paved streets and all utilities. It is reserved; we have similar ones in the area.', 8, (select id from public.municipalities where department_id = 8 and name = 'Distrito Central'), 'Residencial, salida al sur', 14.05, -87.175, 'reserved', 3600000, 240, 12, 20, true, true, true, 'paved', 'full_title', 'flat', true, 6),
  ('b2000000-0000-4000-8000-000000000007', 'terreno-la-ceiba', 'CF-T-207', 'Terreno de 300 m² en La Ceiba', '300 m² lot in La Ceiba', 'Plano, con todos los servicios, cerca del centro.', 'Flat, with all utilities, close to downtown.', 'Terreno de 12 por 25 metros en colonia consolidada, con agua, luz, alcantarillado y calle pavimentada.', '12 by 25 meter lot in an established neighborhood with water, electricity, sewer and a paved street.', 1, (select id from public.municipalities where department_id = 1 and name = 'La Ceiba'), 'Colonia consolidada, sector sur', 15.755, -86.8, 'published', 2100000, 300, 12, 25, true, true, true, 'paved', 'full_title', 'flat', true, 7),
  ('b2000000-0000-4000-8000-000000000008', 'terreno-el-porvenir', 'CF-T-208', 'Terreno grande en El Porvenir', 'Large lot in El Porvenir', '1,000 m² para casa con huerto. Escritura en trámite.', '1,000 m² for a home with a vegetable garden. Title in process.', 'Terreno plano y amplio con agua y luz, a 15 minutos de La Ceiba. La escritura está en trámite: te explicamos el estado legal antes de cualquier pago.', 'Large, flat lot with water and electricity, 15 minutes from La Ceiba. The title is in process: we explain its legal status before any payment.', 1, (select id from public.municipalities where department_id = 1 and name = 'El Porvenir'), 'Aldea sobre la carretera', 15.745, -86.925, 'published', 1850000, 1000, 25, 40, true, true, false, 'gravel', 'title_in_process', 'flat', true, 8),
  ('b2000000-0000-4000-8000-000000000009', 'terreno-siguatepeque', 'CF-T-209', 'Terreno de 420 m² en Siguatepeque', '420 m² lot in Siguatepeque', 'Clima fresco, agua y luz, escritura en regla.', 'Cool climate, water and electricity, clear title.', 'Terreno con leve pendiente y vista a los pinares. Agua y luz en el lugar, calle de balastre en buen estado.', 'Lot with a gentle slope and a view of the pine forest. Water and electricity on site, gravel road in good condition.', 3, (select id from public.municipalities where department_id = 3 and name = 'Siguatepeque'), 'Lotificación en las afueras', 14.612, -87.82, 'published', 1600000, 420, 15, 28, true, true, false, 'gravel', 'full_title', 'gentle_slope', true, 9),
  ('b2000000-0000-4000-8000-000000000010', 'terreno-comayagua', 'CF-T-210', 'Terreno de 250 m² en Comayagua', '250 m² lot in Comayagua', 'El más accesible: plano y con todos los servicios.', 'The most affordable: flat and with all utilities.', 'Terreno de 10 por 25 metros en colonia con calle pavimentada, agua, luz y alcantarillado. Título de dominio útil municipal.', '10 by 25 meter lot in a neighborhood with a paved street, water, electricity and sewer. Municipal useful-domain title.', 3, (select id from public.municipalities where department_id = 3 and name = 'Comayagua'), 'Colonia con calle pavimentada', 14.465, -87.655, 'published', 1150000, 250, 10, 25, true, true, true, 'paved', 'useful_domain', 'flat', true, 10)
